SELECT * FROM clients WHERE age BETWEEN 25 AND 35;
SELECT * FROM clients WHERE ville IN ('Cotonou', 'Porto-Novo');
SELECT * FROM commandes WHERE date_cmd BETWEEN '2025-01-01' AND '2025-12-31';

SELECT * FROM commandes
ORDER BY montant DESC
LIMIT 5;

SELECT c.nom, cmd.montant
FROM clients c
INNER JOIN commandes cmd ON cmd.client_id = c.id;

SELECT c.nom, cmd.montant
FROM clients c
LEFT JOIN commandes cmd ON cmd.client_id = c.id;

SELECT ville, COUNT(*) AS nb_clients, AVG(revenu) AS revenu_moyen
FROM clients
GROUP BY ville;

SELECT ville, annee, COUNT(*) AS nb, AVG(revenu) AS revenu_moyen
FROM clients
GROUP BY ville, annee;

SELECT nom FROM clients
WHERE id IN (SELECT client_id FROM commandes WHERE montant > 50000);

SELECT nom FROM clients c
WHERE EXISTS (SELECT 1 FROM commandes cmd WHERE cmd.client_id = c.id);

SELECT nom FROM clients_2025
UNION
SELECT nom FROM clients_2026;

SELECT UPPER(nom), LOWER(nom), LENGTH(nom),
       SUBSTR(nom, 1, 3), TRIM('  x  '), REPLACE(nom, 'a', 'o')
FROM clients;

SELECT CURRENT_DATE;

SELECT * FROM commandes
WHERE date_cmd >= CURRENT_DATE - INTERVAL '7 days';

CREATE TABLE commandes (
  id INTEGER PRIMARY KEY,
  client_id INTEGER REFERENCES clients(id),
  montant REAL
);

